package pop3

import (
	"bufio"
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"fmt"
	"io"
	"math/big"
	"net"
	"strconv"
	"strings"
	"testing"
	"time"

	"postra/internal/domain"
)

// dial connects to a scripted server on 127.0.0.1 with the real Dialer. An
// empty username skips USER/PASS, which keeps the fixtures to the multi-line
// framing these tests are about.
func dial(t *testing.T, addr string) domain.POP3Session {
	t.Helper()
	host, portStr, err := net.SplitHostPort(addr)
	if err != nil {
		t.Fatal(err)
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		t.Fatal(err)
	}
	sess, err := Dialer{}.Dial(context.Background(), domain.POP3DialOptions{
		Host: host, Port: port, Security: domain.SecurityNone,
	})
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	return sess
}

// maildropServer answers UIDL and LIST with scripted, properly "."-terminated
// multi-line responses. Anything else gets a bare +OK.
func maildropServer(t *testing.T, uidl, list string) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { ln.Close() })
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		br := bufio.NewReader(conn)
		io.WriteString(conn, "+OK POP3 ready\r\n")
		for {
			line, err := br.ReadString('\n')
			if err != nil {
				return
			}
			fields := strings.Fields(line)
			if len(fields) == 0 {
				continue
			}
			switch strings.ToUpper(fields[0]) {
			case "UIDL":
				io.WriteString(conn, "+OK\r\n"+uidl+".\r\n")
			case "LIST":
				io.WriteString(conn, "+OK\r\n"+list+".\r\n")
			case "QUIT":
				io.WriteString(conn, "+OK bye\r\n")
				return
			default:
				io.WriteString(conn, "+OK\r\n")
			}
		}
	}()
	return ln.Addr().String()
}

// selfSigned builds a throwaway server certificate for the STLS fixtures. Ported
// from internal/adapters/smtp/client_test.go, which upgrades the same way.
func selfSigned(t *testing.T) *tls.Config {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	tmpl := &x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: "127.0.0.1"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
		IPAddresses:  []net.IP{net.ParseIP("127.0.0.1")},
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		t.Fatal(err)
	}
	return &tls.Config{Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key}}, MinVersion: tls.VersionTLS12}
}

// stlsServer answers STLS and upgrades, then serves UIDL and LIST over TLS from
// the same loop. inject is appended to the STLS "+OK" in the same write, so the
// injected plaintext reaches the client together with the response it is
// already reading — the shape of a STARTTLS command-injection attempt. The
// returned channel is closed when the server's connection handler returns,
// which is how the tests observe the client hanging up.
func stlsServer(t *testing.T, inject, uidl, list string) (string, <-chan struct{}) {
	t.Helper()
	tlsCfg := selfSigned(t)
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { ln.Close() })
	done := make(chan struct{})
	go func() {
		defer close(done)
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		conn.SetDeadline(time.Now().Add(20 * time.Second))
		br := bufio.NewReader(conn)
		var w io.Writer = conn
		io.WriteString(w, "+OK POP3 ready\r\n")
		for {
			line, err := br.ReadString('\n')
			if err != nil {
				return
			}
			fields := strings.Fields(line)
			if len(fields) == 0 {
				continue
			}
			switch strings.ToUpper(fields[0]) {
			case "STLS":
				if _, err := io.WriteString(w, "+OK begin TLS negotiation\r\n"+inject); err != nil {
					return
				}
				tconn := tls.Server(conn, tlsCfg)
				if err := tconn.Handshake(); err != nil {
					return
				}
				br = bufio.NewReader(tconn)
				w = tconn
			case "UIDL":
				io.WriteString(w, "+OK\r\n"+uidl+".\r\n")
			case "LIST":
				io.WriteString(w, "+OK\r\n"+list+".\r\n")
			case "QUIT":
				io.WriteString(w, "+OK bye\r\n")
				return
			default:
				io.WriteString(w, "+OK\r\n")
			}
		}
	}()
	return ln.Addr().String(), done
}

// dialStartTLS drives the real Dialer through an STLS upgrade. The fixture's
// certificate is self-signed, so verification is skipped here and only here —
// the production default stays false.
func dialStartTLS(t *testing.T, addr string) (domain.POP3Session, error) {
	t.Helper()
	host, portStr, err := net.SplitHostPort(addr)
	if err != nil {
		t.Fatal(err)
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		t.Fatal(err)
	}
	return Dialer{}.Dial(context.Background(), domain.POP3DialOptions{
		Host: host, Port: port, Security: domain.SecurityStartTLS, InsecureSkipVerify: true,
	})
}

// TestPOP3STLSInjectedPlaintextRefusesUpgrade pins the pre-handshake check. TLS
// is client-speaks-first, so a server that has anything left to say after its
// STLS "+OK" is injecting plaintext into the session. Without the check the
// upgrade replaces the reader and the injected bytes are dropped silently, so
// Dial succeeds and nothing records that the server broke the protocol.
func TestPOP3STLSInjectedPlaintextRefusesUpgrade(t *testing.T) {
	addr, done := stlsServer(t, "+OK injected\r\n", "1 abc\r\n", "1 10\r\n")

	sess, err := dialStartTLS(t, addr)
	if err == nil {
		sess.Close()
		t.Fatal("Dial accepted a server that injected plaintext before the STLS handshake")
	}
	if !strings.Contains(err.Error(), "before TLS handshake") {
		t.Fatalf("Dial error = %v, want it to name the pre-handshake bytes", err)
	}

	// The connection must be gone, not left dangling in plaintext.
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("server connection still open after the refused upgrade; want the client to have closed it")
	}
}

// TestPOP3STLSUpgradeRunsCommandsOverTLS is the false-positive guard: a refusal
// on a well-behaved server would stop mail collection outright. A clean upgrade
// must still authenticate nothing, negotiate TLS, and answer UIDL and LIST on
// the encrypted connection.
func TestPOP3STLSUpgradeRunsCommandsOverTLS(t *testing.T) {
	addr, _ := stlsServer(t, "", "1 uid-one\r\n2 uid-two\r\n", "1 2048\r\n2 4096\r\n")

	sess, err := dialStartTLS(t, addr)
	if err != nil {
		t.Fatalf("Dial over a clean STLS upgrade: %v", err)
	}
	defer sess.Close()
	ctx := context.Background()

	msgs, err := sess.UIDL(ctx)
	if err != nil {
		t.Fatalf("UIDL after the upgrade: %v", err)
	}
	if len(msgs) != 2 || msgs[0].UIDL != "uid-one" || msgs[1].UIDL != "uid-two" {
		t.Fatalf("UIDL = %+v, want uid-one and uid-two", msgs)
	}
	sizes, err := sess.List(ctx)
	if err != nil {
		t.Fatalf("LIST after the upgrade: %v", err)
	}
	if len(sizes) != 2 || sizes[0].Size != 2048 || sizes[1].Size != 4096 {
		t.Fatalf("LIST = %+v, want sizes 2048 and 4096", sizes)
	}
	if _, ok := sess.(*session).conn.(*tls.Conn); !ok {
		t.Fatalf("session connection is %T after STLS, want *tls.Conn", sess.(*session).conn)
	}
}

// endlessListServer accepts a command, answers +OK, and then repeats one line
// for as long as the client keeps reading — it never sends the "." that ends a
// multi-line response.
func endlessListServer(t *testing.T, repeated string) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	stop := make(chan struct{})
	t.Cleanup(func() { close(stop); ln.Close() })
	var batch strings.Builder
	for batch.Len() < 4096 {
		batch.WriteString(repeated)
	}
	payload := batch.String()
	go func() {
		conn, err := ln.Accept()
		if err != nil {
			return
		}
		defer conn.Close()
		br := bufio.NewReader(conn)
		io.WriteString(conn, "+OK POP3 ready\r\n")
		for {
			line, err := br.ReadString('\n')
			if err != nil {
				return
			}
			if len(strings.Fields(line)) == 0 {
				continue
			}
			io.WriteString(conn, "+OK\r\n")
			for {
				select {
				case <-stop:
					return
				default:
				}
				if _, err := io.WriteString(conn, payload); err != nil {
					return
				}
			}
		}
	}()
	return ln.Addr().String()
}

// TestPOP3EndlessListResponseDiscardsSession pins the bound readList needs.
// readList collects lines until the server sends "." and refreshes the command
// deadline on every line, so a server that dribbles short lines for ever is
// never stopped by the 60-second command timeout — the enumeration step hangs
// and the collected lines grow without limit.
func TestPOP3EndlessListResponseDiscardsSession(t *testing.T) {
	sess := dial(t, endlessListServer(t, "1 0123456789abcdef0123\r\n"))
	defer sess.Close()
	ctx := context.Background()

	started := time.Now()
	_, err := sess.UIDL(ctx)
	elapsed := time.Since(started)

	if err == nil {
		t.Fatal("UIDL over an unterminated multi-line response returned no error")
	}
	if !strings.Contains(err.Error(), "multi-line response exceeds") {
		t.Fatalf("UIDL error = %v, want it to name the multi-line response bound", err)
	}
	if elapsed > 30*time.Second {
		t.Fatalf("UIDL took %v to give up; want the bound to stop it well inside the 60s command timeout", elapsed)
	}

	// The rest of the response is still on the wire, so the session cannot be
	// reused: both remaining commands must fail rather than read those bytes as
	// protocol.
	if _, err := sess.List(ctx); err == nil {
		t.Fatal("List on the discarded session succeeded; want an error")
	}
	if _, err := sess.Retrieve(ctx, 1); err == nil {
		t.Fatal("Retrieve on the discarded session succeeded; want an error")
	}
}

// TestPOP3EndlessBlankLinesDiscardSession is the same attack with the cheapest
// line there is. textproto.ReadLine strips the CRLF, so a bare "\r\n" comes back
// as zero bytes: an accounting that charges only len(line) never advances at all
// and readList appends "" for ever while the deadline keeps being pushed out.
// Charging every line the terminator it really cost plus the header it occupies
// is what makes the bound reachable here — the IMAP adapter took a review for
// exactly this bypass.
func TestPOP3EndlessBlankLinesDiscardSession(t *testing.T) {
	sess := dial(t, endlessListServer(t, "\r\n"))
	defer sess.Close()
	ctx := context.Background()

	started := time.Now()
	_, err := sess.UIDL(ctx)
	elapsed := time.Since(started)

	if err == nil {
		t.Fatal("UIDL over an endless run of blank lines returned no error")
	}
	if !strings.Contains(err.Error(), "multi-line response exceeds") {
		t.Fatalf("UIDL error = %v, want it to name the multi-line response bound", err)
	}
	if elapsed > 30*time.Second {
		t.Fatalf("UIDL took %v to give up; want the bound to stop it well inside the 60s command timeout", elapsed)
	}
}

// TestPOP3FullMaildropStaysUnderListBound is the regression guard on the bound's
// size. A large maildrop is enumerated in one multi-line response, so the bound
// has to clear the biggest legitimate one by a wide margin. It measures what a
// full-length UIDL response actually costs against the bound and fails if the
// margin closes — and proves the normal path still parses byte-for-byte.
func TestPOP3FullMaildropStaysUnderListBound(t *testing.T) {
	const count = 5000
	const uidPrefix = "uuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuu" // 65 chars; + %05d = the RFC 1939 maximum of 70
	var uidl, list strings.Builder
	for i := 1; i <= count; i++ {
		fmt.Fprintf(&uidl, "%d %s%05d\r\n", i, uidPrefix, i)
		fmt.Fprintf(&list, "%d %d\r\n", i, 2048+i)
	}
	wire := uidl.String()

	sess := dial(t, maildropServer(t, wire, list.String()))
	defer sess.Close()
	ctx := context.Background()

	msgs, err := sess.UIDL(ctx)
	if err != nil {
		t.Fatalf("enumerate a %d-message maildrop (%d bytes of UIDL response): %v", count, len(wire), err)
	}
	if len(msgs) != count {
		t.Fatalf("UIDL returned %d messages, want %d", len(msgs), count)
	}
	for i, m := range msgs {
		wantN := i + 1
		wantUID := fmt.Sprintf("%s%05d", uidPrefix, wantN)
		if m.Number != wantN || m.UIDL != wantUID {
			t.Fatalf("UIDL entry %d = {Number:%d UIDL:%q}, want {Number:%d UIDL:%q}", i, m.Number, m.UIDL, wantN, wantUID)
		}
	}
	sizes, err := sess.List(ctx)
	if err != nil {
		t.Fatalf("list a %d-message maildrop: %v", count, err)
	}
	if len(sizes) != count {
		t.Fatalf("LIST returned %d messages, want %d", len(sizes), count)
	}
	for i, m := range sizes {
		if m.Number != i+1 || m.Size != int64(2048+i+1) {
			t.Fatalf("LIST entry %d = {Number:%d Size:%d}, want {Number:%d Size:%d}", i, m.Number, m.Size, i+1, 2048+i+1)
		}
	}

	// What that response cost the bound: the CRLF is stripped before the line is
	// charged and re-charged as part of listLineOverhead.
	charged := int64(len(wire)-2*count) + int64(count)*listLineOverhead
	perMessage := charged / count
	t.Logf("a %d-message UIDL response is %d bytes on the wire, charged %d against the %d-byte bound (%d per message, so the bound admits %d messages)",
		count, len(wire), charged, int64(maxListBytes), perMessage, int64(maxListBytes)/perMessage)
	if charged*8 > maxListBytes {
		t.Fatalf("a %d-message enumeration is charged %d bytes, within 8x of the %d-byte bound; the bound leaves no margin", count, charged, int64(maxListBytes))
	}
	// The real sizing constraint is maildrop scale, not this fixture: a bound
	// that cannot hold a few hundred thousand maximum-length UIDs would break
	// real maildrops rather than runaway servers.
	const wantMessages = 300000
	if perMessage*wantMessages > maxListBytes {
		t.Fatalf("at %d charged bytes per message the %d-byte bound admits only %d messages, fewer than the %d a large maildrop holds",
			perMessage, int64(maxListBytes), int64(maxListBytes)/perMessage, wantMessages)
	}
}
// Package pop3 implements a minimal RFC 1939 client behind the
// domain.POP3Dialer port. Supports implicit TLS (995), STLS upgrade, and —
// for offline / air-gapped networks — plaintext with optional
// authentication. Policy gating for insecure modes happens in the
// application layer, not here.
package pop3

import (
	"bytes"
	"context"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/textproto"
	"strconv"
	"strings"
	"time"

	"postra/internal/domain"
)

// maxListBytes caps how much of one multi-line response (LIST, UIDL) readList
// may accumulate. Nothing else bounds it: readList collects lines until the
// server sends the terminating ".", and it refreshes the command deadline on
// every line it reads, so a server that keeps dribbling short lines and never
// terminates the response holds the collecting worker for ever with no deadline
// left to stop it. That is worse here than on the IMAP side, where the same
// shape was closed in v0.23.7: readList runs in the enumeration step (the sync
// loop's UIDL, then LIST), so one such maildrop stalls a whole account's sync
// before the first message is touched.
//
// The bound has to clear the biggest legitimate maildrop, which arrives in a
// single response: a UIDL line is a message number, a space and a unique-id of
// at most 70 characters (RFC 1939 §7), charged at 92 bytes per message by
// TestPOP3FullMaildropStaysUnderListBound. 32 MiB therefore leaves room for
// roughly 364,000 messages in one maildrop while still bounding a runaway
// response — 8 MiB, the IMAP figure, would refuse a maildrop of 91,000.
const maxListBytes = 32 << 20

// listLineOverhead is what every line of a multi-line response costs on top of
// the bytes textproto.ReadLine returns, and without it maxListBytes does not
// hold. A line arrives with its CRLF already stripped, so a bare "\r\n" measures
// zero: charging only len(line), a server that answers with nothing but blank
// lines never advances the total at all and readList appends "" for ever, which
// is the runaway the bound exists to stop. A retained line also costs a 16-byte
// string header in lines, so at one byte per line a 32 MiB total would sit on
// far more live heap than the bound suggests. Charging the two bytes the server
// really sent plus that header closes both. The IMAP adapter carries the same
// constant as responseLineOverhead, added for exactly this bypass.
const listLineOverhead = 2 + 16

type Dialer struct{}

func (Dialer) Dial(ctx context.Context, opts domain.POP3DialOptions) (domain.POP3Session, error) {
	addr := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
	connectTO := secondsOr(opts.ConnectTimeoutSec, 15)
	d := &net.Dialer{Timeout: connectTO}

	var conn net.Conn
	var err error
	tlsCfg := &tls.Config{
		ServerName: opts.Host,
		MinVersion: tls.VersionTLS12,
		// #nosec G402 -- offline/self-hosted POP3 servers may use self-signed
		// certs; skipping verification is an explicit per-account opt-in
		// (default false), required by offline-network mail support.
		InsecureSkipVerify: opts.InsecureSkipVerify,
	}
	switch opts.Security {
	case domain.SecurityTLS:
		conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
	case domain.SecurityStartTLS, domain.SecurityNone:
		conn, err = d.DialContext(ctx, "tcp", addr)
	default:
		return nil, fmt.Errorf("unknown security mode %q", opts.Security)
	}
	if err != nil {
		return nil, fmt.Errorf("pop3 connect %s: %w", addr, err)
	}

	s := &session{
		conn:      conn,
		text:      textproto.NewConn(conn),
		commandTO: secondsOr(opts.CommandTimeoutSec, 60),
	}
	if _, err := s.readResponse(); err != nil {
		conn.Close()
		return nil, fmt.Errorf("pop3 greeting: %w", err)
	}

	if opts.Security == domain.SecurityStartTLS {
		if _, err := s.cmd("STLS"); err != nil {
			conn.Close()
			return nil, fmt.Errorf("STLS: %w", err)
		}
		// TLS is client-speaks-first: after the "+OK" that grants the upgrade a
		// conforming server sends nothing until it has seen the ClientHello. So
		// anything already sitting in the reader is plaintext the server pushed
		// ahead of the handshake — a STARTTLS command injection (CVE-2011-0411
		// and the 2021 "NO STARTTLS" survey), whose payload the upgrade below
		// would otherwise discard along with the old reader, leaving the session
		// to continue as if nothing had happened. Refusing is the safe verdict,
		// and it cannot cost a well-behaved server anything.
		//
		// Best-effort by construction: only bytes that reached this buffer are
		// visible, so an injection still in flight in the kernel or on the wire
		// goes unseen. It narrows the window rather than closing it.
		if n := s.text.R.Buffered(); n > 0 {
			conn.Close()
			return nil, fmt.Errorf("STLS: server sent %d bytes before TLS handshake", n)
		}
		tconn := tls.Client(conn, tlsCfg)
		if err := tconn.HandshakeContext(ctx); err != nil {
			conn.Close()
			return nil, fmt.Errorf("STLS handshake: %w", err)
		}
		s.conn = tconn
		s.text = textproto.NewConn(tconn)
	}

	// Authentication is optional: some maildrops on isolated networks accept
	// sessions without USER/PASS.
	if opts.Username != "" {
		if _, err := s.cmd("USER %s", opts.Username); err != nil {
			s.Close()
			return nil, &AuthError{Err: fmt.Errorf("USER: %w", err)}
		}
		pass := ""
		if opts.Password != nil {
			pass = string(opts.Password.Reveal())
		}
		_, err := s.cmd("PASS %s", pass)
		pass = ""
		_ = pass
		if err != nil {
			s.Close()
			return nil, &AuthError{Err: fmt.Errorf("PASS rejected: %w", err)}
		}
	}
	return s, nil
}

// AuthError aliases the shared domain type so the sync layer can recognize
// credential failures from any inbound adapter (POP-011).
type AuthError = domain.AuthError

type session struct {
	conn      net.Conn
	text      *textproto.Conn
	commandTO time.Duration
}

func (s *session) deadline() { s.conn.SetDeadline(time.Now().Add(s.commandTO)) }

func (s *session) readResponse() (string, error) {
	s.deadline()
	line, err := s.text.ReadLine()
	if err != nil {
		return "", err
	}
	if !strings.HasPrefix(line, "+OK") {
		return "", fmt.Errorf("server: %s", line)
	}
	return line, nil
}

func (s *session) cmd(format string, args ...any) (string, error) {
	s.deadline()
	if err := s.text.PrintfLine(format, args...); err != nil {
		return "", err
	}
	return s.readResponse()
}

// readList collects a multi-line response up to its "." terminator, bounded by
// maxListBytes so an unterminated response cannot hold the session for ever.
func (s *session) readList() ([]string, error) {
	var lines []string
	var charged int64
	for {
		s.deadline()
		line, err := s.text.ReadLine()
		if err != nil {
			return nil, err
		}
		if line == "." {
			return lines, nil
		}
		charged += int64(len(line)) + listLineOverhead
		if charged > maxListBytes {
			// The rest of the response is still on the wire and its length is
			// unknown, so the offset the next command would read at is
			// unknowable: discard the session rather than let a later command
			// mistake those bytes for its own reply.
			s.conn.Close()
			return nil, fmt.Errorf("pop3 multi-line response exceeds %d bytes", int64(maxListBytes))
		}
		lines = append(lines, strings.TrimPrefix(line, "."))
	}
}

func (s *session) List(ctx context.Context) ([]domain.RemoteMessage, error) {
	if _, err := s.cmd("LIST"); err != nil {
		return nil, err
	}
	lines, err := s.readList()
	if err != nil {
		return nil, err
	}
	var out []domain.RemoteMessage
	for _, l := range lines {
		var n int
		var size int64
		if _, err := fmt.Sscanf(l, "%d %d", &n, &size); err == nil {
			out = append(out, domain.RemoteMessage{Number: n, Size: size})
		}
	}
	return out, nil
}

func (s *session) UIDL(ctx context.Context) ([]domain.RemoteMessage, error) {
	if _, err := s.cmd("UIDL"); err != nil {
		return nil, err // caller falls back to LIST + content hash (POP-005)
	}
	lines, err := s.readList()
	if err != nil {
		return nil, err
	}
	var out []domain.RemoteMessage
	for _, l := range lines {
		parts := strings.SplitN(strings.TrimSpace(l), " ", 2)
		if len(parts) != 2 {
			continue
		}
		n, err := strconv.Atoi(parts[0])
		if err != nil {
			continue
		}
		out = append(out, domain.RemoteMessage{Number: n, UIDL: strings.TrimSpace(parts[1])})
	}
	return out, nil
}

// retrBody reads a multi-line response body with dot-unstuffing.
func (s *session) retrBody() (io.ReadCloser, error) {
	var buf bytes.Buffer
	for {
		s.deadline()
		line, err := s.text.ReadLineBytes()
		if err != nil {
			return nil, err
		}
		if len(line) == 1 && line[0] == '.' {
			break
		}
		if len(line) > 1 && line[0] == '.' {
			line = line[1:]
		}
		buf.Write(line)
		buf.WriteString("\r\n")
	}
	return io.NopCloser(&buf), nil
}

func (s *session) Retrieve(ctx context.Context, number int) (io.ReadCloser, error) {
	if _, err := s.cmd("RETR %d", number); err != nil {
		return nil, err
	}
	return s.retrBody()
}

func (s *session) Top(ctx context.Context, number, lines int) (io.ReadCloser, error) {
	if _, err := s.cmd("TOP %d %d", number, lines); err != nil {
		return nil, err
	}
	return s.retrBody()
}

func (s *session) Delete(ctx context.Context, number int) error {
	_, err := s.cmd("DELE %d", number)
	return err
}

func (s *session) Quit(ctx context.Context) error {
	_, err := s.cmd("QUIT")
	s.conn.Close()
	return err
}

func (s *session) Close() error { return s.conn.Close() }

func secondsOr(v, def int) time.Duration {
	if v <= 0 {
		v = def
	}
	return time.Duration(v) * time.Second
}
package domain

import (
	"context"
	"errors"
)

// ErrNotFound is the canonical "record does not exist" error returned by any
// Storage adapter, so transports can map it to 404 without importing a
// specific adapter package.
var ErrNotFound = errors.New("not found")

// SecretRef is an opaque reference to a secret held in a SecretStore.
// Only references travel through the application layer, REST DTOs, and MCP
// tool arguments — never secret values (SEC-KEY-001/004).
type SecretRef string

// SecretPurpose is recorded on every acquisition for auditing.
type SecretPurpose string

const (
	PurposePOP3Auth    SecretPurpose = "pop3_auth"
	PurposeSMTPAuth    SecretPurpose = "smtp_auth"
	PurposeAIKey       SecretPurpose = "ai_api_key"
	PurposeTest        SecretPurpose = "connection_test"
	PurposeOIDC        SecretPurpose = "oidc_client_secret"
	PurposeVectorToken SecretPurpose = "vector_store_token"
)

type SecretType string

const (
	SecretMailPassword SecretType = "mail_password"
	SecretAPIKey       SecretType = "api_key"
)

// SecretHandle carries a decrypted secret for the shortest possible scope.
// It cannot be marshaled or stringified: String/MarshalJSON always redact
// (SEC-KEY-006). Adapters call Reveal immediately before dialing and Zero
// right after (SEC-KEY-005).
type SecretHandle struct {
	value []byte
}

func NewSecretHandle(v []byte) *SecretHandle {
	c := make([]byte, len(v))
	copy(c, v)
	return &SecretHandle{value: c}
}

func (h *SecretHandle) Reveal() []byte {
	if h == nil {
		return nil
	}
	return h.value
}

func (h *SecretHandle) Zero() {
	if h == nil {
		return
	}
	for i := range h.value {
		h.value[i] = 0
	}
	h.value = nil
}

func (h *SecretHandle) String() string { return "[REDACTED]" }

func (h *SecretHandle) MarshalJSON() ([]byte, error) {
	return nil, errors.New("SecretHandle must not be serialized")
}

func (h *SecretHandle) GoString() string { return "[REDACTED]" }

type PutSecretRequest struct {
	OwnerUserID string
	Type        SecretType
	Provider    string // "local", "vault", ...
	Value       *SecretHandle
	Label       string
}

type RotateSecretRequest struct {
	Value *SecretHandle
}

// SecretStore is the provider-independent secret port. Implementations:
// local encrypted file store (personal mode), Vault/OpenBao (server mode).
// There is deliberately no "Get plaintext" API beyond Acquire, and Acquire
// results must stay inside adapters (SEC-KEY-003).
type SecretStore interface {
	Put(ctx context.Context, req PutSecretRequest) (SecretRef, error)
	Acquire(ctx context.Context, ref SecretRef, purpose SecretPurpose) (*SecretHandle, error)
	Rotate(ctx context.Context, ref SecretRef, req RotateSecretRequest) error
	Revoke(ctx context.Context, ref SecretRef) error
}

// StoredSecret is an envelope-encrypted secret persisted in the shared
// database. Keeping the ciphertext alongside the CredentialRef that names it
// (rather than in a per-node local file) is what lets a secret survive a pod
// restart and be read by every replica (SEC-KEY-003: still only ciphertext at
// rest; the plaintext never leaves an adapter after Acquire).
type StoredSecret struct {
	Ref      string
	Owner    string
	Type     SecretType
	Label    string
	Envelope string // JSON-encoded crypto.Envelope (ciphertext + wrapped DEK)
	Version  int
	Revoked  bool
}

// CredentialRef is the DB-visible metadata about a secret (never the value).
type CredentialRef struct {
	Ref        SecretRef  `json:"ref"`
	OwnerID    string     `json:"owner_id"`
	Type       SecretType `json:"type"`
	Provider   string     `json:"provider"`
	Label      string     `json:"label"`
	Status     string     `json:"status"` // active | revoked
	Version    int        `json:"version"`
	CreatedAt  int64      `json:"created_at"`
	LastUsedAt int64      `json:"last_used_at,omitempty"`
}
